        [Route("PreviewFromYaml")]
        [HttpPost]
        [IgnoreAntiforgeryToken]
        public IActionResult PreviewFromYaml([FromBody] PreviewEndpointWorkflowYamlRequest request)
        {
            var yaml = request?.Yaml?.Trim() ?? string.Empty;
            if (string.IsNullOrWhiteSpace(yaml))
            {
                return Json(new
                {
                    ok = false,
                    message = "Enter workflow YAML to preview.",
                    plantUml = string.Empty,
                    svgUrl = string.Empty
                });
            }

            try
            {
                var workflow = WorkflowDeserializer.ParseWorkflow(yaml);
                var plantUml = workflow.GenerateSequenceDiagram();
                var encoded = workflow.GetEncodedPlantUml();
                return Json(new
                {
                    ok = true,
                    message = (string)null,
                    plantUml,
                    svgUrl = $"https://www.plantuml.com/plantuml/svg/{encoded}"
                });
            }
            catch (Exception ex)
            {
                return Json(new
                {
                    ok = false,
                    message = ex.Message,
                    plantUml = string.Empty,
                    svgUrl = string.Empty
                });
            }
        }

        [Route("GetUmlDiagram/{workflowId:int}")]
        [HttpGet]
        public async Task<IActionResult> GetUmlDiagram(int workflowId)
        {
            using var fileResponse = await pageClient.EndpointWorkflowsGetItemDiagramAsync(workflowId).ConfigureAwait(false);

            if (fileResponse.Stream == null)
                return NotFound("Diagram image not found.");

            var contentType = "image/svg+xml";
            if (fileResponse.Headers.TryGetValue("Content-Type", out var values))
            {
                contentType = values.FirstOrDefault() ?? contentType;
            }

            using var memoryStream = new MemoryStream();
            await fileResponse.Stream.CopyToAsync(memoryStream).ConfigureAwait(false);
            var fileBytes = memoryStream.ToArray();

            Response.Headers.CacheControl = "no-store";
            return File(fileBytes, contentType);
        }

        [Route("GetUml/{workflowId:int}")]
