            return Content(diagramUml, "text/plain");
        }

        [Route("UpdateEndpointWorkflow")]
        [HttpPost]
        [IgnoreAntiforgeryToken]
        public async Task<JsonResult> UpdateEndpointWorkflow(UpdateEndpointWorkflow request)
        {
            if (request == null || request.Id <= 0)
                return Json(false);

            try
            {
                var eventData = await pageClient.EndpointWorkflowsGetItemAsync(request.Id).ConfigureAwait(false);
                if (eventData == null)
                    return Json(false);

                eventData.IsActive = request.Value == 1;
                await pageClient.EndpointWorkflowsUpdateAsync(request.Id, eventData).ConfigureAwait(false);
                return Json(true);
            }
            catch
            {
                return Json(false);
            }
        }

        private async Task<EndpointWorkflowData> LoadEndpointWorkflowsForModule(
            EndpointWorkflowData model,
            string moduleName)
        {
            model ??= new EndpointWorkflowData();
            model.PageSize = PageSize;
            if (model.CurrentPage < 1)
                model.CurrentPage = 1;

            model.ComboList ??= new Dictionary<string, Dictionary<string, string>>();
            model.List = new List<EndpointWorkflowDto>();

            var normalized = (moduleName ?? string.Empty).Trim();
            try
            {
                var rows = await pageClient.EndpointWorkflowsGetEndpointWorkflowsAsync().ConfigureAwait(false);
                model.List = (rows ?? [])
                    .Where(r => string.Equals(
                        (r.ModuleName ?? string.Empty).Trim(),
                        normalized,
                        StringComparison.OrdinalIgnoreCase))
                    .OrderBy(r => r.Name)
                    .Select(r => new EndpointWorkflowDto
                    {
                        Id = r.Id,
                        Name = r.Name,
                        ModuleName = r.ModuleName,
                        EndpointPath = r.EndpointPath,
                        HttpMethod = r.HttpMethod,
                        Description = r.Description,
                        WorkflowContent = r.WorkflowContent,
                        IsActive = r.IsActive
                    })
                    .ToList();
            }
            catch
            {
                model.List = new List<EndpointWorkflowDto>();
            }

            model.NumberOfRecord = model.List?.Count ?? 0;
            model.TotalPage = model.PageSize <= 0
                ? 0
                : (model.NumberOfRecord / model.PageSize) + (model.NumberOfRecord % model.PageSize == 0 ? 0 : 1);
            if (model.CurrentPage == int.MaxValue)
                model.CurrentPage = Math.Max(model.TotalPage, 1);

            SetModelBinder(ref model);
            model.SelectedItem = new EndpointWorkflowDto
            {
                ModuleName = normalized,
                HttpMethod = "GET",
                IsActive = true,
                WorkflowContent = string.Empty
            };
            return model;
        }

        private async Task<List<EndpointWorkflowCardVm>> LoadCardsAsync()
        {
            try
            {
                var rows = await pageClient.EndpointWorkflowsGetEndpointWorkflowsAsync().ConfigureAwait(false);
                return (rows ?? [])
                    .Select(row => ToCard(row))
                    .Where(x => x != null)
                    .Cast<EndpointWorkflowCardVm>()
                    .ToList();
            }
            catch
            {
                return [];
            }
        }

        private static EndpointWorkflowCardVm? ToCard(GetEndpointWorkflowsResponseDto? row)
        {
            if (row == null)
                return null;

            return new EndpointWorkflowCardVm
            {
                Id = row.Id.ToString(),
                Name = row.Name?.Trim() ?? "Untitled",
                ModuleName = row.ModuleName?.Trim() ?? "Workflows",
                EndpointPath = row.EndpointPath?.Trim() ?? string.Empty,
                HttpMethod = string.IsNullOrWhiteSpace(row.HttpMethod)
                    ? "POST"
                    : row.HttpMethod.Trim().ToUpperInvariant(),
                Description = row.Description,
                IsActive = row.IsActive,
                WorkflowContent = row.WorkflowContent
            };
        }

        private async Task EnrichEndpointWorkflowFormAsync(EndpointWorkflowData model)
        {
            model.ComboList ??= new Dictionary<string, Dictionary<string, string>>();
            model.ComboList["HttpMethods"] = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
            {
                ["GET"] = "GET",
                ["POST"] = "POST",
                ["PUT"] = "PUT",
                ["PATCH"] = "PATCH",
                ["DELETE"] = "DELETE"
            };

            var modules = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            try
            {
                var modulesClient = HttpContext.RequestServices.GetService<IModulesClient>();
                if (modulesClient != null)
                {
                    var result = await modulesClient.ModulesListAsync(1, 500).ConfigureAwait(false);
                    foreach (var mod in result?.Items ?? [])
                    {
                        var name = (mod.Name ?? string.Empty).Trim();
                        if (!string.IsNullOrEmpty(name))
                            modules[name] = name;
                    }
                }
            }
            catch
            {
                // Fall through to workflow-derived module names.
            }

            if (modules.Count == 0)
            {
                try
                {
                    var rows = await pageClient.EndpointWorkflowsGetEndpointWorkflowsAsync().ConfigureAwait(false);
                    foreach (var row in rows ?? [])
                    {
                        var name = (row.ModuleName ?? string.Empty).Trim();
                        if (!string.IsNullOrEmpty(name))
                            modules[name] = name;
                    }
                }
                catch
                {
                    // Leave empty; form still renders.
                }
            }

            var selectedModule = (model.SelectedItem?.ModuleName ?? string.Empty).Trim();
            if (!string.IsNullOrEmpty(selectedModule) && !modules.ContainsKey(selectedModule))
                modules[selectedModule] = selectedModule;

            model.ComboList["Modules"] = modules
                .OrderBy(x => x.Key, StringComparer.OrdinalIgnoreCase)
                .ToDictionary(x => x.Key, x => x.Value, StringComparer.OrdinalIgnoreCase);
        }
